-- Descriptions for the ancient Annalist and Herald questions: what happened and why it is worth knowing.
-- Keyed by (name, year) so one write-up serves the Annalist event and the Herald battle of the same name. Idempotent.
create temp table d (name text, yr integer, txt text);
update public.year_guess_items t set description = d.txt from d where lower(btrim(t.event)) = lower(d.name) and t.correct_year = d.yr;
update public.casualties_multiplier_items t set description = d.txt from d where lower(btrim(t.battle)) = lower(d.name) and t.year = d.yr;
drop table d;
